select a.file_status as fileStatus,a.vital_status as vitalStatus,p.patient_id as patientId, a.patient_appt_id as apptId, p.umr_num as patientCode, a.priority_no as priorityNo,p.patient_name as pname,p.gender as gender,p.mob_num as mobNum, p.pat_cat as catValue, TIMESTAMPDIFF(YEAR,p.dob,CURDATE()) as age, fn_getcodevalue(a.appt_status_id) as statusInfo, a.op_num as opCode, fn_getcodevalue_id('SCH','a.appt_status_id') as statusInfoId, fn_getcodevalue(a.visit_type) as visitType, p.city as city,p.village as village, a.diseases_desc as problem,a.token_num as tokenNum, DATE_FORMAT(a.schedule_dt,'%d-%b-%Y') as apptDt from at_pr_patient p,at_pr_appt a, at_security_users sec where p.patient_id=a.patient_id and a.emp_id = sec.emp_id and sec.user_id = #{userId}
and a.schedule_dt = #{selectDate} order by priority_no
and a.schedule_dt = CURDATE() order by priority_no

select  v.val_name as visitStatus,v.val_code_icon as statusIcon,v.val_code_bg_color as statusBgColor 
 from at_std_code_values v,at_std_code s where s.std_code = 'SCH' and v.std_code_id = s.std_code_id and  
 v.val_name!='Scheduled' and v.val_name!='Rescheduled' and v.val_name!='ConsReVisit' and v.val_name!='ConsReVisitN';

SELECT p.patient_id as patientId,pic_details as picName,p.city as city,p.addr as addr, p.umr_num as patientCode, p.patient_name as pname, p.gender, p.mob_num as mobNum, date_format(p.reg_dt,'%d-%b-%Y') as regDt, p.credit_org_id as orgName, p.patient_category as pntCat,date_format(p.dob,'%d-%b-%Y') as dob, age as age,age_m as ageMonths,age_d as ageDays FROM at_pr_patient p WHERE p.status_id in (fn_getcodevalue_id ('STS', 'Active'),fn_getcodevalue_id ('PATSTS', 'Active'))
and (p.reg_dt BETWEEN NOW() - INTERVAL 1200 DAY AND NOW())
and reg_dt between DATE_FORMAT(STR_TO_DATE(#{fromDate}, '%e-%b-%Y'), '%Y-%m-%d') and DATE_FORMAT(STR_TO_DATE(#{toDate}, '%e-%b-%Y'), '%Y-%m-%d')
and reg_dt = DATE_FORMAT(STR_TO_DATE(#{fromDate}, '%e-%b-%Y'), '%Y-%m-%d')
and p.umr_num = #{umrNo}
and (p.patient_name sounds like #{pname} or p.patient_name like #{patientLike})
and p.mob_num = #{mobNum}
and p.gender = #{gender}
and p.dob = DATE_FORMAT(STR_TO_DATE(#{dob}, '%e-%b-%Y'), '%Y-%m-%d')

