update at_pr_appt set appt_status_id = fn_getcodevalue_id('SCH',#{status}),token_num = #{tokenNum},
start_time = #{startTime}, end_time= #{endTime},modified_by = #{modifiedBy},
modified_on=now(),modified_ip=#{modifiedIp} where patient_appt_id = #{apptId}

